# -*- coding: utf-8 -*-
"""CERF VOLANT - nouvelle maquette de Maeva (08/10), 12 cartons/feuille.

REGLE ABSOLUE : le decor EST son carton (le titre CERF VOLANT, le cerf-volant
souriant + nuage + ficelle a noeuds, le << N deg ___ >>, les 6 cases), releve
au trait. RIEN n'a ete redessine ni ajoute.

CE QUE MAEVA M'A DEMANDE : un numero dans chaque case (6 numeros).
   Plages CERF VOLANT : 2x(1-15) . 2x(16-30) . 1x(46-60) . 1x(61-75).
     bloc 2x2 : colonne gauche = 1-15 (petit en haut), colonne droite = 16-30
     case du milieu  -> 46-60
     case en bas-droite -> 61-75
   Crieur : 1-30 + 46-75 (le 31-45 n'existe pas).

DISPOSITION : A4 PORTRAIT, 12 cartons en 3 colonnes x 4 rangees (carton carre).
On reprend UN carton et on le pose 12 fois -> leger et rapide a l'impression.
"""
import io
import random
from reportlab.pdfgen import canvas
from reportlab.lib.pagesizes import A4
from reportlab.lib import colors
from reportlab.lib.units import mm
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont

try:
    from generators import securite as _sec
except Exception:
    try:
        import securite as _sec
    except Exception:
        _sec = None
_sec = None  # chiffres pleins -> impression rapide sur la Sharp

import os as _os
try:
    pdfmetrics.registerFont(TTFont("LMROMANCV", _os.path.join(
        _os.path.dirname(_os.path.abspath(__file__)), "LatinModern.ttf")))
    _POLICE_ECO = "LMROMANCV"
except Exception:
    try:
        pdfmetrics.registerFont(TTFont("DJLCV", "/usr/share/fonts/truetype/dejavu/DejaVuSans-ExtraLight.ttf"))
        _POLICE_ECO = "DJLCV"
    except Exception:
        _POLICE_ECO = "Helvetica"
POLICE = _POLICE_ECO
_GRIS_ECO = colors.Color(0.40, 0.40, 0.40)
_POLICE_P15 = "Helvetica-Bold"
_GRIS_P15 = colors.Color(0.14, 0.14, 0.14)


def _style_chiffres(style):
    if str(style).lower() in ("p15", "premium"):
        return _POLICE_P15, _GRIS_P15
    return _POLICE_ECO, _GRIS_ECO


RAINBOW = [
    "#E53935", "#FB8C00", "#F9A825", "#43A047", "#00ACC1",
    "#1E88E5", "#3949AB", "#8E24AA", "#D81B60", "#6D4C41",
]
GRIS = colors.Color(0.42, 0.42, 0.42)
GRIS_CLAIR = colors.Color(0.80, 0.80, 0.80)
TRAIT_NB = "#555555"

PAGE_W, PAGE_H = A4
ASPECT = 0.9789                 # largeur / hauteur du carton (quasi carre)
COLS_PAGE = 3
ROWS_PAGE = 4
CARTES_PAGE = COLS_PAGE * ROWS_PAGE

MARGE_X = 6 * mm
GUTTER = 4 * mm
CELL_W = (PAGE_W - 2 * MARGE_X - (COLS_PAGE - 1) * GUTTER) / COLS_PAGE
CELL_H = CELL_W / ASPECT
_BLOC_H = ROWS_PAGE * CELL_H + (ROWS_PAGE - 1) * GUTTER
MARGE_Y = (PAGE_H - _BLOC_H) / 2.0

# serie discrete sur la ligne << N deg ___ >> (en haut a gauche)
_SERIE_FX = 0.140
_SERIE_FY = 0.072
_T_SERIE = 6.5

# (fx, fy, largeur, hauteur, index_du_numero) en fractions du carton
CELLULES = [
    (0.1723, 0.2545, 0.2277, 0.2199, 0),
    (0.1708, 0.4864, 0.2246, 0.2199, 1),
    (0.4154, 0.2545, 0.2338, 0.2199, 2),
    (0.4123, 0.4864, 0.2338, 0.2199, 3),
    (0.6415, 0.7063, 0.2123, 0.2078, 4),
    (0.8600, 0.8599, 0.2062, 0.2018, 5),
]

def _positions():
    pos = []
    for r in range(ROWS_PAGE):
        for col in range(COLS_PAGE):
            px = MARGE_X + col * (CELL_W + GUTTER)
            py = PAGE_H - MARGE_Y - (r + 1) * CELL_H - r * GUTTER
            pos.append((px, py))
    return pos


def _graver_planche(c):
    nom = "CERFVOLANT_12_DECOR"
    if not getattr(c, "_cv_forme", False):
        c.beginForm(nom, lowerx=0, lowery=0, upperx=CELL_W, uppery=CELL_H)
        p = c.beginPath()
        for contour in _DECOR.split("|"):
            i = 0; n = len(contour)
            while i < n:
                cmd = contour[i]; j = i + 1
                while j < n and contour[j] not in "mlc":
                    j += 1
                v = [float(x) for x in contour[i + 1:j].split(",")]
                if cmd == "m":
                    p.moveTo(v[0] / 1000.0 * CELL_W, CELL_H - v[1] / 1000.0 * CELL_H)
                elif cmd == "l":
                    p.lineTo(v[0] / 1000.0 * CELL_W, CELL_H - v[1] / 1000.0 * CELL_H)
                else:
                    p.curveTo(v[0] / 1000.0 * CELL_W, CELL_H - v[1] / 1000.0 * CELL_H,
                              v[2] / 1000.0 * CELL_W, CELL_H - v[3] / 1000.0 * CELL_H,
                              v[4] / 1000.0 * CELL_W, CELL_H - v[5] / 1000.0 * CELL_H)
                i = j
            p.close()
        c.drawPath(p, stroke=0, fill=1)
        c.endForm()
        c._cv_forme = True
    return nom


def _gen_grille(rng):
    c1 = sorted(rng.sample(range(1, 16), 2))     # 1-15 (petit en haut)
    c2 = sorted(rng.sample(range(16, 31), 2))    # 16-30
    n4 = rng.randint(46, 60)                     # case du milieu
    n5 = rng.randint(61, 75)                     # case bas-droite
    return [c1[0], c1[1], c2[0], c2[1], n4, n5]


def _tirer(rng, deja):
    for _ in range(400):
        g = _gen_grille(rng)
        cle = tuple(g)
        if cle not in deja:
            deja.add(cle); return g
    return g


def _dessiner_feuille(c, grilles, series, couleurs, style="eco"):
    police_ch, gris_ch = _style_chiffres(style)
    nom = _graver_planche(c)
    _w88 = pdfmetrics.stringWidth("88", police_ch, 1.0)
    for gi, (px, py) in enumerate(_positions()):
        c.saveState()
        fen = c.beginPath(); fen.rect(px, py, CELL_W, CELL_H)
        c.clipPath(fen, stroke=0, fill=0)
        c.setFillColor(couleurs[gi])
        c.translate(px, py)
        c.doForm(nom)
        c.restoreState()
        nums = grilles[gi]
        for (fx, fy, fw, fh, idx) in CELLULES:
            val = nums[idx]
            mx = px + fx * CELL_W
            my = py + CELL_H - fy * CELL_H
            tnum = min(fw * CELL_W * 0.80 / _w88, fh * CELL_H * 0.76 / 0.72)
            c.setFillColor(gris_ch); c.setFont(police_ch, tnum)
            c.drawCentredString(mx, my - tnum * 0.34, str(val))
        c.setFillColor(GRIS); c.setFont(POLICE, _T_SERIE)
        c.drawCentredString(px + _SERIE_FX * CELL_W,
                            py + CELL_H - _SERIE_FY * CELL_H, "%06d" % series[gi])


def generer_pdf(nb_cartes=12, serie_start=1, theme="", couleur=True,
                nom_evenement="", titre_jeu="", couleur_perso="", date_lieu="",
                telephone="", style="eco", evenement_id="", motif="", page_start=1, **_):
    buf = io.BytesIO()
    c = canvas.Canvas(buf, pagesize=A4, pageCompression=1)
    nb_cartes = max(1, min(int(nb_cartes), 10000))
    nb_pages = (nb_cartes + CARTES_PAGE - 1) // CARTES_PAGE
    rng = random.Random(661900 + int(serie_start))
    serie = int(serie_start)
    no_page = max(1, int(page_start))
    _deja = set()
    for _p in range(nb_pages):
        if nom_evenement:
            c.setFillColor(colors.black); c.setFont(POLICE, 8)
            c.drawCentredString(PAGE_W / 2, PAGE_H - 4.4 * mm, nom_evenement)
        c.setFillColor(GRIS_CLAIR); c.setFont(POLICE, 5.5)
        c.drawRightString(PAGE_W - 5 * mm, PAGE_H - 4.4 * mm, "%03d" % no_page)
        grilles = [_tirer(rng, _deja) for _k in range(CARTES_PAGE)]
        series = [serie + k for k in range(CARTES_PAGE)]
        couleurs = [colors.HexColor(
            couleur_perso if (couleur and couleur_perso)
            else RAINBOW[(s - 1) % len(RAINBOW)] if couleur else TRAIT_NB)
            for s in series]
        _dessiner_feuille(c, grilles, series, couleurs, style=style)
        serie += CARTES_PAGE
        c.showPage()
        no_page += 1
    c.save(); buf.seek(0)
    return buf


if __name__ == "__main__":
    open("test_cerf_volant_12.pdf", "wb").write(generer_pdf(nb_cartes=12).read())
    print("CERF VOLANT - 12 cartons genere")


